// class key → [family, talent profile]
export const TOP_DAMAGE_CLASS_PROFILE: Readonly<Record<string, readonly [string, string]>> = {"Beginner":["beginner","base"],"Journeyman":["beginner","t20_24"],"Maestro":["beginner","t20_24_31"],"Voidwalker":["beginner","t20_24_31"],"Warrior":["warrior","t86_95_97"],"Barbarian":["warrior","t86_95_97_110"],"Blood_Berserker":["warrior","t86_95_97_110"],"Death_Bringer":["warrior","t86_95_97_110"],"Squire":["warrior","t86_95_97_123_125"],"Divine_Knight":["warrior","t86_95_97_123_125"],"Archer":["archer","t277_284"],"Bowman":["archer","t277_284_290"],"Siege_Breaker":["archer","t277_284_290"],"Hunter":["archer","t277_284_305"],"Beast_Master":["archer","t277_284_305"],"Wind_Walker":["archer","t277_284_305"],"Mage":["mage","t446_455_457_463"],"Shaman":["mage","t446_455_457_463_485"],"Bubonic_Conjuror":["mage","t446_455_457_463_485"],"Arcane_Cultist":["mage","t446_455_457_463_485"],"Wizard":["mage","t446_455_457_463_470"],"Elemental_Sorcerer":["mage","t446_455_457_463_470"],"Royal_Guardian":["warrior","t86_95_97_123_125"]};

// Family used when no class is known (the highest-reaching one).
export const TOP_DAMAGE_DEFAULT_FAMILY = "warrior";

/** The top Damage reference for a class — its family's base merged with its profile. */
export function topDamageFlatForClass(classKey: string | null | undefined): FlatMap {
  const [family, profile] = (classKey && TOP_DAMAGE_CLASS_PROFILE[classKey]) || [TOP_DAMAGE_DEFAULT_FAMILY, "base"];
  const base = TOP_DAMAGE_FAMILY_FLAT[family] ?? TOP_DAMAGE_FAMILY_FLAT[TOP_DAMAGE_DEFAULT_FAMILY];
  const override = TOP_DAMAGE_PROFILE_OVERRIDES[`${family}:${profile}`];
  return override ? { ...base, ...override } : base;
}
